import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
  const { currentUser, logout, isAdmin } = useAuth();

  return (
    <nav className="bg-white shadow-md">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center">
            <Link to="/" className="flex-shrink-0 text-xl font-bold text-indigo-600">
              AuthApp
            </Link>
            <div className="hidden md:block">
              <div className="ml-10 flex items-baseline space-x-4">
                <Link to="/" className="text-gray-600 hover:text-indigo-700 px-3 py-2 rounded-md text-sm font-medium">Home</Link>
                {!currentUser && <Link to="/login" className="text-gray-600 hover:text-indigo-700 px-3 py-2 rounded-md text-sm font-medium">Login</Link>}
                {!currentUser && <Link to="/register" className="text-gray-600 hover:text-indigo-700 px-3 py-2 rounded-md text-sm font-medium">Register</Link>}
                {/* Link to user dashboard only if logged in */}
                {currentUser && <Link to="/dashboard" className="text-gray-600 hover:text-indigo-700 px-3 py-2 rounded-md text-sm font-medium">My Dashboard</Link>}
                {/* Link to admin dashboard only if user is admin */}
                {isAdmin() && <Link to="/admin/dashboard" className="text-red-600 hover:text-red-700 px-3 py-2 rounded-md text-sm font-medium font-semibold">Admin Dashboard</Link>}
              </div>
            </div>
          </div>
          <div className="hidden md:block">
            <div className="ml-4 flex items-center md:ml-6">
              {currentUser ? (
                <div className="flex items-center space-x-4">
                  <span className="text-gray-700">Welcome, {currentUser.username}!</span>
                  <button
                    onClick={logout}
                    className="bg-red-500 hover:bg-red-700 text-white px-4 py-2 rounded-md text-sm font-medium focus:outline-none focus:ring-2 focus:ring-red-400"
                  >
                    Logout
                  </button>
                </div>
              ) : (
                <Link to="/login" className="bg-indigo-500 hover:bg-indigo-700 text-white px-4 py-2 rounded-md text-sm font-medium focus:outline-none focus:ring-2 focus:ring-indigo-400">
                  Sign In
                </Link>
              )}
            </div>
          </div>
          {/* Mobile Menu Button removed to avoid undefined variables */}
        </div>
      </div>
      {/* Mobile Menu section removed */}
    </nav>
  );
};

export default Navbar;
